let backendCompiler=null;
function stopBackendWorkspace(){if(backendCompiler){window.removeEventListener('message',backendCompiler.listener);backendCompiler=null;}}
function backendWorkKey(){return 'web-talim:backend:'+activeData().assignment.draftId;}
function renderBackendAssignment(data){
 const a=data.assignment,panel=document.createElement('section');panel.id='panel5';panel.hidden=true;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','tab5');
 const executable=['node','sql'].includes(a.mode),editor=a.mode!=='report';
 panel.innerHTML=`<h2>Amaliy mashg‘ulot</h2><p>${backendEscape(a.task)}</p><h3>Bajarish tartibi</h3><ol>${a.steps.map(x=>`<li>${backendEscape(x)}</li>`).join('')}</ol><h3>Namuna va kutiladigan natija</h3><pre class="lesson-code"><code>${backendEscape(a.code)}</code></pre><p>${backendEscape(a.expected)}</p>${editor?'<label for="be-code" class="lab-label">Kod yoki buyruqlar</label><textarea id="be-code" class="lab-editor" spellcheck="false"></textarea><div class="lab-actions"><button class="retry" type="button" onclick="downloadBackendCode()">Kodni yuklab olish ↓</button><button class="retry" type="button" onclick="resetBackendCode()">Namuna kodini tiklash</button></div>':''}${executable?`<section class="online-compiler"><h3>${a.mode==='sql'?'SQLite':'Node.js'} onlayn konsoli</h3><p>Quyidagi tugma tashqi OneCompiler muharririni ochadi. Kodni yuklang, so‘ng <b>▶ Run</b> bosing. Natija o‘sha oynaning Console qismida chiqadi.</p><p class="muted">Node 24 va modul mavjudligini tashqi xizmat belgilaydi. node:sqlite ishlamasa, konspektdagi misolni lokal Node 24 LTSda bajaring. Bu konsol lokal serveringiz uchun ommaviy HTTP manzil yaratmaydi.</p><div class="lab-actions"><button type="button" class="cta" onclick="openBackendCompiler()">Muharrirni ochish</button><button type="button" class="retry" onclick="populateBackendCompiler()">Kodni muharrirga yuklash</button></div><p id="be-compiler-status" role="status">Muharrir hali ochilmagan.</p><div id="be-compiler-holder"></div><div class="compiler-runbar"><button class="cta" type="button" id="be-run" disabled onclick="runBackendCompiler()">▶ Run</button><span>Natija tashqi muharrirning Console qismida chiqadi.</span></div><p class="compiler-disclosure">Kod tashqi OneCompiler xizmatiga yuboriladi. Faqat mashq qiymatlarini kiriting. <a href="https://onecompiler.com/${a.mode==='sql'?'sqlite':'javascript'}" target="_blank" rel="noopener">Alohida oynada ochish ↗</a></p></section>`:'<h3>Lokal muhitda bajarish</h3><p>Ushbu ish sxema, bir nechta fayl, terminal, loyiha parchasi yoki brauzer integratsiyasiga tegishli. Uni yuqoridagi bajarish tartibiga amal qilib o‘z kompyuteringizda bajaring. Hisobotga kuzatuv va natijani yozing.</p>'}<h3>Tekshirish mezonlari</h3>${a.criteria.map(x=>`<label class="option"><input class="be-check" type="checkbox"> ${backendEscape(x)}</label>`).join('')}<label for="be-report" class="lab-label">Hisobot — bajarilgan ish, natija, xato va tuzatish</label><textarea class="lab-editor" id="be-report" spellcheck="false"></textarea><p id="be-save" class="muted" role="status">Ish shu brauzerda saqlanadi. Amaliy ishni o‘qituvchi mezonlar bo‘yicha tekshiradi.</p><div class="lab-actions"><button class="retry" type="button" onclick="downloadBackendReport()">Hisobotni yuklab olish ↓</button><button class="cta" type="button" onclick="openResource(3)">Test sinoviga o‘tish →</button></div>${a.unit>=39?'<p><a href="materials/m6-backend-loyiha.zip" download>Yakuniy loyiha, README va testlarni yuklab olish ↓</a></p>':''}`;
 document.querySelector('.article').appendChild(panel);let saved={};try{saved=JSON.parse(localStorage.getItem(backendWorkKey())||'{}');}catch(e){}
 if(editor)document.getElementById('be-code').value=saved.code??a.code;
 document.getElementById('be-report').value=saved.report??'';panel.querySelectorAll('.be-check').forEach((el,i)=>el.checked=!!saved.checks?.[i]);panel.querySelectorAll('textarea,input').forEach(el=>el.addEventListener('input',saveBackendWork));
}
function saveBackendWork(){try{localStorage.setItem(backendWorkKey(),JSON.stringify({code:document.getElementById('be-code')?.value||'',report:document.getElementById('be-report').value,checks:[...document.querySelectorAll('.be-check')].map(x=>x.checked)}));document.getElementById('be-save').textContent='Shu brauzerda saqlandi; boshqa qurilmaga avtomatik ko‘chmaydi.';}catch(e){document.getElementById('be-save').textContent='Saqlash mavjud emas. Kod va hisobotni yuklab oling.';}}
function backendDownload(text,name){const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function downloadBackendCode(){const mode=activeData().assignment.mode;backendDownload(document.getElementById('be-code').value,`m6-${currentLesson}.${mode==='sql'?'sql':mode==='browser'?'js':['terminal','files'].includes(mode)?'txt':'cjs'}`);}
function downloadBackendReport(){backendDownload(document.getElementById('be-report').value,`m6-${currentLesson}-hisobot.txt`);}
function resetBackendCode(){document.getElementById('be-code').value=activeData().assignment.code;saveBackendWork();}
function backendCompilerCode(){const a=activeData().assignment,code=document.getElementById('be-code').value;if(a.mode!=='sql')return code;
 if(a.unit===17)return code+'\nSELECT name FROM sqlite_master WHERE type=\'table\';';
 const schema='PRAGMA foreign_keys=ON;\nCREATE TABLE users(id INTEGER PRIMARY KEY,name TEXT NOT NULL);\nINSERT INTO users VALUES(1,\'Ali\'),(2,\'Vali\');\nCREATE TABLE tasks(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),title TEXT NOT NULL,done INTEGER DEFAULT 0);\nINSERT INTO tasks VALUES(1,1,\'Dars\',0),(2,1,\'Kitob\',1);\n';return schema+code+(a.unit===19?'\nSELECT id,done FROM tasks WHERE id=1;':'');
}
function openBackendCompiler(){if(backendCompiler)return;const a=activeData().assignment;if(!['node','sql'].includes(a.mode))return;
 const language=a.mode==='sql'?'sqlite':'javascript',frame=document.createElement('iframe');frame.id='backend-compiler-frame';frame.title=language==='sqlite'?'SQLite onlayn muharriri':'Node.js onlayn muharriri';frame.src=`https://onecompiler.com/embed/${language}?listenToEvents=true&codeChangeEvent=true&hideNew=true&theme=dark`;frame.style='width:100%;height:650px;border:0;border-radius:10px';frame.referrerPolicy='strict-origin-when-cross-origin';
 const listener=event=>{if(event.source!==frame.contentWindow||event.origin!=='https://onecompiler.com'||!backendCompiler)return;const files=event.data?.files;if(!Array.isArray(files))return;const file=files.find(f=>typeof f?.content==='string'&&f.content.length<=200000);if(file&&a.mode==='node'){document.getElementById('be-code').value=file.content;saveBackendWork();}};
 backendCompiler={frame,listener,language};window.addEventListener('message',listener);frame.addEventListener('load',()=>{if(backendCompiler?.frame!==frame)return;document.getElementById('be-run').disabled=false;document.getElementById('be-compiler-status').textContent='Muharrir yuklandi. Kodni yuklab ▶ Run bosing.';populateBackendCompiler();});document.getElementById('be-compiler-holder').appendChild(frame);
}
function populateBackendCompiler(){openBackendCompiler();if(!backendCompiler)return;const {frame,language}=backendCompiler;frame.contentWindow.postMessage({eventType:'populateCode',language,files:[{name:language==='sqlite'?'queries.sql':'index.js',content:backendCompilerCode()}]},'https://onecompiler.com');}
function runBackendCompiler(){if(!backendCompiler)return;backendCompiler.frame.contentWindow.postMessage({eventType:'triggerRun'},'https://onecompiler.com');document.getElementById('be-compiler-status').textContent='Run buyrug‘i yuborildi. Natija yoki xatoni tashqi muharrirning Console qismida ko‘ring.';}
